<script setup lang="ts">
import { reactive } from 'vue'
import { router } from '@inertiajs/vue3'
import { route } from 'ziggy-js'
import type { EstadoCuenta } from '../../types'

const props = defineProps<{ estadoCuenta: EstadoCuenta }>()
const filters = reactive({ fecha_desde: props.estadoCuenta.periodo.desde, fecha_hasta: props.estadoCuenta.periodo.hasta })
const reload = () => router.get(route('cartera.show', [props.estadoCuenta.edificio.id, props.estadoCuenta.departamento.id]), filters, { preserveState: true, preserveScroll: true, replace: true })
</script>

<template>
  <UDashboardPanel id="estado-cuenta"><template #header><UDashboardNavbar :title="`Estado de cuenta · ${estadoCuenta.departamento.codigo}`"><template #leading><UDashboardSidebarCollapse /></template><template #right><UButton icon="i-lucide-hand-coins" label="Registrar pago" variant="outline" @click="router.visit(route('pagos.create', { edificio_id: estadoCuenta.edificio.id, departamento_id: estadoCuenta.departamento.id }))" /></template></UDashboardNavbar></template><template #body><div class="mx-auto flex w-full max-w-6xl flex-col gap-5 p-4 sm:p-6"><UCard><div class="grid gap-4 md:grid-cols-4"><div><p class="text-xs uppercase text-muted">Departamento</p><p>{{ estadoCuenta.departamento.codigo }} · {{ estadoCuenta.departamento.nombre }}</p></div><div><p class="text-xs uppercase text-muted">Titular(es) al corte</p><p>{{ estadoCuenta.propietarios.map(item => item.nombre).join(', ') || 'Sin titular vigente' }}</p></div><UFormField label="Desde"><UInput v-model="filters.fecha_desde" type="date" @change="reload" /></UFormField><UFormField label="Hasta"><UInput v-model="filters.fecha_hasta" type="date" @change="reload" /></UFormField></div></UCard><div class="grid gap-3 sm:grid-cols-3"><UCard><p class="text-xs uppercase text-muted">Saldo inicial</p><p class="mt-2 font-mono text-lg">${{ estadoCuenta.saldoInicial.neto }}</p></UCard><UCard><p class="text-xs uppercase text-muted">Débitos / créditos</p><p class="mt-2 font-mono">${{ estadoCuenta.resumen.debitos }} / ${{ estadoCuenta.resumen.creditos }}</p></UCard><UCard><p class="text-xs uppercase text-muted">Saldo final</p><p class="mt-2 font-mono text-lg font-semibold">${{ estadoCuenta.saldoFinal.neto }}</p></UCard></div><div class="overflow-x-auto rounded-xl border border-default"><table class="w-full min-w-5xl text-left text-sm"><thead class="bg-elevated/50 text-xs uppercase tracking-wide text-muted"><tr><th class="p-3">Fecha</th><th class="p-3">Tipo</th><th class="p-3">Referencia</th><th class="p-3 text-right">Débito</th><th class="p-3 text-right">Crédito</th><th class="p-3 text-right">Saldo</th></tr></thead><tbody class="divide-y divide-default"><tr v-for="movimiento in estadoCuenta.movimientos" :key="movimiento.id"><td class="p-3">{{ movimiento.fecha }}</td><td class="p-3 capitalize">{{ movimiento.tipo.replaceAll('_', ' ') }}</td><td class="p-3">{{ movimiento.referencia }}<p v-if="movimiento.aplicaciones?.length" class="mt-1 text-xs text-muted">{{ movimiento.aplicaciones.map(item => `${item.concepto} $${item.montoAplicado}`).join(' · ') }}</p></td><td class="p-3 text-right font-mono">{{ movimiento.debito === '0.0000' ? '—' : `$${movimiento.debito}` }}</td><td class="p-3 text-right font-mono">{{ movimiento.credito === '0.0000' ? '—' : `$${movimiento.credito}` }}</td><td class="p-3 text-right font-mono font-semibold">${{ movimiento.saldoAcumulado }}</td></tr><tr v-if="!estadoCuenta.movimientos.length"><td class="p-8 text-center text-muted" colspan="6">No hay movimientos en el rango seleccionado.</td></tr></tbody></table></div></div></template></UDashboardPanel>
</template>
